def extract_sublease_fields(sublease_message):
    sublease_dict = {}
    for field in ['monthly_rent', 'bedrooms', 'is_furnished', 'pets_allowed', 'available_from']:
        value = sublease_message.get(field)
        if value is not None:
            sublease_dict[field] = value
    return sublease_dict

